const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
function write(rel, name, value){
  const out = path.join(root, rel);
  fs.writeFileSync(out, `/* generated by scripts/bundle_runtime.js */\nwindow.${name}=${JSON.stringify(value)};\n`);
}

function csvCell(v){
  const s = Array.isArray(v) ? v.join(' | ') : (v ?? '').toString();
  return /[",\n]/.test(s) ? '"'+s.replace(/"/g,'""')+'"' : s;
}
function writeCsv(rel, headers, rows){
  const out=path.join(root,rel);
  const text=[headers.join(','),...rows.map(r=>headers.map(h=>csvCell(r[h])).join(','))].join('\n')+'\n';
  fs.writeFileSync(out,text,'utf8');
}

global.window = {DOT_DATA:require('./assemble_data')()};
write('data/data_bundle.js','DOT_DATA',window.DOT_DATA);

// The complete canonical export remains available offline. Visitors receive only
// the searchable index; record details are requested in eight bounded batches.
const full=window.DOT_DATA,version=JSON.parse(fs.readFileSync(path.join(root,'package.json'))).version;
const shardFor=label=>[...label].reduce((h,c)=>(h*31+c.charCodeAt(0))>>>0,0)%8;
const fields=['string','asciiString','recordLevel','ianaProfile','rootListed','currentRootStatus','status','type','entity','registryCountry','registryCountryCode','round','historicalRounds','originRound','editorialDesignation','themes','applicationEntity','geography','representedPlace','group','noteKey','readingKey','strange','city','contentionCount','placeholder','programRound','introductionPath','introductionBasis','applicationCount','applicationRounds','applicationApplicants','governanceCaseIds','economicCaseIds','socialCaseIds'];
const searchFields=r=>[r.technicalContactOrganization,r.administrativeContactOrganization,r.whoisServer,r.registryUrl,...(r.rdapServers||[]),...(r.nameServers||[]).flatMap(n=>[n.hostname,...n.ipAddresses])].filter(Boolean).join(' ');
const index=full.explorer.map(r=>({...Object.fromEntries(fields.filter(k=>r[k]!==undefined).map(k=>[k,r[k]])),technicalSearch:searchFields(r),profileShard:shardFor(r.asciiString),sourceUrl:r.source?.[0]||''}));
const site={...full,explorer:index,profileDelivery:{version,shards:8}};
site.releaseHistory=JSON.parse(fs.readFileSync(path.join(root,'data/release_history.json'),'utf8'));
write('data/site_bundle.js','DOT_DATA',site);
for(let shard=0;shard<8;shard++){
 const payload={version,records:Object.fromEntries(full.explorer.filter(r=>shardFor(r.asciiString)===shard).map(r=>[r.asciiString,r]))};
 fs.writeFileSync(path.join(root,`data/explorer_profiles_${shard}.js`),`/* generated: load only when a record is opened */\nwindow.DOT_PROFILE_CHUNKS=window.DOT_PROFILE_CHUNKS||{};\nwindow.DOT_PROFILE_CHUNKS[${shard}]=${JSON.stringify(payload)};\n`);
}

const catalogHeaders=['string','round','status','type','entity','group','geography','themes','contention_count','strange','city','placeholder','provenance','sources','current_root_status','current_as_of','formal_type','editorial_designation','origin_round','historical_rounds','registry_entity','registry_country','technical_contact_organization','technical_contact_country','represented_place','application_entity','registration_date','contention_year','origin_round_sources','ascii_string','record_level','root_listed','iana_profile','registry_country_code','administrative_contact_organization','administrative_contact_country','administrative_contact_country_code','technical_contact_country_code','last_updated','source_retrieved_at','registry_url','whois_server','rdap_servers','name_server_count','iana_report_count','program_round','introduction_path','introduction_basis','introduction_path_sources','application_count','application_rounds','application_applicants'];
writeCsv('data/explorer_catalog.csv', catalogHeaders, (window.DOT_DATA.explorer||[]).map(r=>({
  string:r.string,round:r.round,status:r.status,type:r.type,entity:r.entity,group:r.group,geography:r.geography,themes:r.themes||[],contention_count:r.contentionCount??'',strange:r.strange?'yes':'no',city:r.city?'yes':'no',placeholder:r.placeholder?'yes':'no',provenance:r.provenanceKey?(r.provenanceKey+(r.provenanceDate?' · '+r.provenanceDate:'')):'',sources:r.source||[],current_root_status:r.currentRootStatus,current_as_of:r.currentAsOf,formal_type:r.formalType,editorial_designation:r.editorialDesignation,origin_round:r.originRound,historical_rounds:r.historicalRounds,registry_entity:r.registryEntity,registry_country:r.registryCountry,technical_contact_organization:r.technicalContactOrganization,technical_contact_country:r.technicalContactCountry,represented_place:r.representedPlace,application_entity:r.applicationEntity,registration_date:r.registrationDate,contention_year:r.contentionYear,origin_round_sources:r.originRoundSources||[],ascii_string:r.asciiString,record_level:r.recordLevel,root_listed:r.rootListed?'yes':'no',iana_profile:r.ianaProfile?'yes':'no',registry_country_code:r.registryCountryCode,administrative_contact_organization:r.administrativeContactOrganization,administrative_contact_country:r.administrativeContactCountry,administrative_contact_country_code:r.administrativeContactCountryCode,technical_contact_country_code:r.technicalContactCountryCode,last_updated:r.lastUpdated,source_retrieved_at:r.sourceRetrievedAt,registry_url:r.registryUrl,whois_server:r.whoisServer,rdap_servers:r.rdapServers||[],name_server_count:r.ianaProfile?r.nameServers.length:'',iana_report_count:r.ianaProfile?r.ianaReports.length:'',program_round:r.programRound,introduction_path:r.introductionPath,introduction_basis:r.introductionBasis,introduction_path_sources:r.introductionPathSources||[],application_count:r.applicationCount||0,application_rounds:r.applicationRounds||[],application_applicants:r.applicationApplicants||[]
})));
writeCsv('data/explorer_nameservers.csv',['string','ascii_string','hostname','ip_addresses','sources','source_retrieved_at'],window.DOT_DATA.explorer.flatMap(r=>(r.nameServers||[]).map(n=>({string:r.string,ascii_string:r.asciiString,hostname:n.hostname,ip_addresses:n.ipAddresses,sources:r.source[0],source_retrieved_at:r.sourceRetrievedAt}))));
writeCsv('data/explorer_iana_reports.csv',['string','ascii_string','title','publication_date','url','sources','source_retrieved_at'],window.DOT_DATA.explorer.flatMap(r=>(r.ianaReports||[]).map(report=>({string:r.string,ascii_string:r.asciiString,title:report.title,publication_date:report.date,url:report.url,sources:r.source[0],source_retrieved_at:r.sourceRetrievedAt}))));

